import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	// Root container
	const root = new THREE.Object3D();
	root.name = config.id ?? 'feature-thumbnail-card';

	// Apply transforms from config (fallback to specification defaults)
	const pos = config.position ?? [-1.25, -1.1, 0];
	const rot = config.rotation ?? [0, 0, 0];
	const scl = config.scale ?? [1, 1, 1];

	root.position.set(pos[0], pos[1], pos[2]);
	root.rotation.set(rot[0], rot[1], rot[2]);
	root.scale.set(scl[0], scl[1], scl[2]);

	// Load GLB mesh (synchronous via cached loader)
	const glb = ctx.glbLoader(config.meshUrl);
	// Assume loader returns an Object3D (Group or Scene)
	const meshRoot = glb.scene ? glb.scene.clone() : glb.clone ? glb.clone() : glb;
	root.add(meshRoot);

	// Apply cinematic primitives
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params ?? {});
			}
		}
	}

	// ---------- Event Handlers ----------
	const handlers = {};

	// Hover: rise‑in (y +0.15 → original) using GSAP preset‑like config
	const baseY = root.position.y;
	const hoverTL = gsap.timeline({ paused: true });
	hoverTL.to(
		root.position,
		{
			y: baseY + 0.15,
			duration: 0.15,
			ease: 'power3.out',
		},
		0
	);
	handlers.hover = () => {
		hoverTL.restart();
	};

	// Click: emit navigation event
	handlers.click = () => {
		if (typeof ctx.emit === 'function') {
			ctx.emit('hub-features.select');
		}
	};

	// Attach handlers to userData
	root.userData.handlers = handlers;

	// ---------- Cleanup ----------
	root.userData.cleanup = () => {
		// Kill GSAP timeline(s)
		hoverTL.kill();

		// Dispose geometry and material resources
		meshRoot.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				if (Array.isArray(obj.material)) {
					obj.material.forEach((m) => m && m.dispose && m.dispose());
				} else if (obj.material) {
					obj.material.dispose();
				}
			}
		});
	};

	return root;
}
